SELECT COUNT(*)
FROM users
WHERE USER_ID = #{userId}

SELECT COUNT(*)
FROM store_user
WHERE USER_ID = #{userId}

SELECT
    USER_ID AS userId,
    USER_NAME AS userName
FROM users
WHERE USER_NAME = #{userName}
  AND USER_PWD = #{pwd}

SELECT
    USER_ID AS userId,
    USER_NAME AS userName,
    PHONE
FROM users
WHERE USER_ID = #{userId}
  AND USER_NAME = #{userName}
  AND PHONE = #{phone}

mapper.update:
UPDATE users
SET USER_PWD = #{pwd}
WHERE USER_ID = #{userId}
